  "Paiement impossible pour le moment.": {'en': "Payment not possible right now.", 'es': "Pago no disponible en este momento.", 'de': "Zahlung im Moment nicht möglich.", 'ar': "الدفع غير ممكن حاليًا.", 'pt': "Pagamento indisponível no momento.", 'zh': "暂时无法支付。", 'sw': "Malipo hayawezekani kwa sasa."},
  "Cette publication n'a aucun média à télécharger.": {'en': "This post has no media to download.", 'es': "Esta publicación no tiene contenido para descargar.", 'de': "Dieser Beitrag hat kein Medium zum Herunterladen.", 'ar': "لا يحتوي هذا المنشور على ملف للتنزيل.", 'pt': "Esta publicação não tem mídia para baixar.", 'zh': "此帖子没有可下载的媒体。", 'sw': "Chapisho hili halina media ya kupakua."},
