  "Impossible de charger les vidéos de tes abonnements pour le moment.": {'en': "Can't load videos from your follows right now.", 'es': "No se pueden cargar los vídeos de tus seguidos ahora.", 'de': "Die Videos deiner Abos können gerade nicht geladen werden.", 'ar': "تعذّر تحميل فيديوهات من تتابعهم حاليًا.", 'pt': "Não foi possível carregar os vídeos de quem você segue.", 'zh': "暂时无法加载你关注的视频。", 'sw': "Haiwezekani kupakia video za unaowafuata sasa."},
  "Aucune vidéo de tes abonnements pour l'instant.": {'en': "No videos from your follows yet.", 'es': "Aún no hay vídeos de tus seguidos.", 'de': "Noch keine Videos aus deinen Abos.", 'ar': "لا توجد فيديوهات ممن تتابعهم حتى الآن.", 'pt': "Ainda não há vídeos de quem você segue.", 'zh': "暂时没有你关注的视频。", 'sw': "Bado hakuna video za unaowafuata."},
  "Vérifie ta connexion puis réessaie.": {'en': "Check your connection and try again.", 'es': "Comprueba tu conexión e inténtalo de nuevo.", 'de': "Prüfe deine Verbindung und versuche es erneut.", 'ar': "تحقق من اتصالك ثم أعد المحاولة.", 'pt': "Verifique sua conexão e tente novamente.", 'zh': "请检查网络后重试。", 'sw': "Angalia muunganisho wako kisha ujaribu tena."},
  "Suis des créateurs pour voir leurs vidéos ici, ou découvre « Pour toi ».": {'en': "Follow creators to see their videos here, or discover “For you”.", 'es': "Sigue a creadores para ver sus vídeos aquí, o descubre «Para ti».", 'de': "Folge Creatorn, um ihre Videos hier zu sehen, oder entdecke „Für dich“.", 'ar': "تابع صنّاع المحتوى لترى فيديوهاتهم هنا، أو اكتشف «لك».", 'pt': "Siga criadores para ver os vídeos deles aqui, ou descubra «Para você».", 'zh': "关注创作者即可在此看到他们的视频，或去看看“为你推荐”。", 'sw': "Fuata watayarishaji ili uone video zao hapa, au gundua «Kwako»."},
  "Réessayer": {'en': "Try again", 'es': "Reintentar", 'de': "Erneut versuchen", 'ar': "أعد المحاولة", 'pt': "Tentar novamente", 'zh': "重试", 'sw': "Jaribu tena"},
