  "Retire l'effet de temps appliqué.": {'en': "Removes the time effect applied.", 'es': "Quita el efecto de tiempo aplicado.", 'de': "Entfernt den angewendeten Zeiteffekt.", 'ar': "يُزيل تأثير الوقت المطبّق.", 'pt': "Remove o efeito de tempo aplicado.", 'zh': "移除已应用的时间效果。", 'sw': "Huondoa athari ya muda iliyotumika."},
  "Reprendre ton brouillon": {'en': "Resume your draft", 'es': "Retoma tu borrador", 'de': "Entwurf fortsetzen", 'ar': "استأنف مسودتك", 'pt': "Retome seu rascunho", 'zh': "继续你的草稿", 'sw': "Endelea na rasimu yako"},
  "Une vidéo en cours de retouche": {'en': "A video being edited", 'es': "Un video en edición", 'de': "Ein Video in Bearbeitung", 'ar': "فيديو قيد التعديل", 'pt': "Um vídeo em edição", 'zh': "正在编辑的视频", 'sw': "Video inayohaririwa"},
  "Une photo en cours de retouche": {'en': "A photo being edited", 'es': "Una foto en edición", 'de': "Ein Foto in Bearbeitung", 'ar': "صورة قيد التعديل", 'pt': "Uma foto em edição", 'zh': "正在编辑的照片", 'sw': "Picha inayohaririwa"},
